const savedVolume=loadAudioPref('volume');if(savedVolume!==null&&Number.isFinite(+savedVolume))music.setVolume(clamp(+savedVolume/100,0,1));
const savedTrack=loadAudioPref('track');if(PokeMusic.tracks[savedTrack])music.setTrack(savedTrack);
$('track').value=music.track;$('musicVolume').value=Math.round(music.volume*100);$('volumeValue').textContent=Math.round(music.volume*100)+'%';
function musicUI(){let playing=music.enabled;$('music').textContent=playing?'♫ MUSIC ON':'♫ MUSIC OFF';$('music').setAttribute('aria-pressed',String(playing));$('nowPlaying').textContent=playing?'NOW PLAYING · '+PokeMusic.tracks[music.track].name:musicTouched?'Original 8-bit tunes · tap MUSIC to listen':'Original 8-bit tunes · starts at kickoff'}
