const skill=(name,value)=>`<div class="skill"><span>${name}</span><span class="meter"><i style="width:${value}%"></i></span><b>${value}</b></div>`;
function playerHeader(p){return `<div class="card-top"><img src="assets/${p.id}.png" alt=""><div><h3>${p.name}</h3><small>${p.pos} · ${p.side.toUpperCase()}</small></div><div class="ovr">${p.ovr}<small>OVR</small></div></div>`}
function renderRatings(){ $('ratings').innerHTML=roster.filter(p=>p.side===side).map(p=>`<button class="player-card" data-player="${p.id}" aria-label="View ${p.name} ${p.pos} scouting report">${playerHeader(p)}${specs[p.pos].map(k=>skill(k,p.ratings[k])).join('')}</button>`).join('');document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{let p=roster.find(p=>p.id===+b.dataset.player);$('playerReport').innerHTML=playerHeader(p)+`<p>${p.note}</p>`+Object.entries(p.ratings).map(([k,v])=>skill(k,v)).join('');$('playerDialog').showModal()})}
const columns={offense:[['att','ATT'],['cmp','CMP'],['passYds','PASS YD'],['passTD','PASS TD'],['ints','INT'],['rush','CAR'],['rushYds','RUSH YD'],['rushTD','RUSH TD'],['targets','TGT'],['rec','REC'],['recYds','REC YD'],['recTD','REC TD']],defense:[['snaps','SNAPS'],['tackles','TKL'],['sacks','SACK'],['picks','INT'],['pressures','PRESS'],['blocks','KEY BLK']]};
