 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=step;p.x+=p.vx*step;p.y+=p.vy*step;p.vx*=Math.exp(-step*3);p.vy+=step*(p.kind==='confetti'?-3:-.5);if(p.life<=0)particles.splice(i,1)}shake*=Math.exp(-step*15);
