 if(fullEffects&&p.move&&!down){ctx.fillStyle=p.team===0?'#a0d9ed':'#f4aa8c';let feet=Math.sin(stride)*5;ctx.fillRect(p.tx-10+feet,py+7,5,5);ctx.fillRect(p.tx+4-feet,py+10,5,4);if(p.carrier&&p.p.ratings.Speed>85){ctx.strokeStyle='#e3f7b570';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(p.tx-12+i*11,py+21);ctx.lineTo(p.tx-15+i*11,py+34);ctx.stroke()}}}
 ctx.save();ctx.translate(p.tx,py-bob-p.jump);ctx.rotate(rock+p.lean+down*(p.pose==='dive'||p.pose==='miss'?-.5:1)*Math.PI/2);if(p.pose==='kick'&&fullEffects){ctx.rotate(.24);ctx.scale(1.05,.95)}else if(p.pose==='throw'&&fullEffects){ctx.rotate(-.19);ctx.scale(1.08,.94)}else if(p.pose==='block'&&fullEffects){ctx.scale(1.03,.97)}else if(p.pose==='celebrate'&&fullEffects){ctx.rotate(Math.sin(elapsed*9)*.12)}ctx.imageSmoothingEnabled=false;let img=images[p.p.id];if(img?.complete&&img.naturalWidth)ctx.drawImage(img,-34,-42,68,68);ctx.restore();
